package com.bank.loansimulation.adapters.out.jdbc;

import com.bank.loansimulation.domain.port.SimulationRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;

/** JDBC adapter of the SimulationRepository port. Records are insert-only. */
@Repository
public class JdbcSimulationRepository implements SimulationRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcSimulationRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public int save(BigDecimal monto, Integer plazo, BigDecimal tasaAnual, BigDecimal cuotaMensual,
                    BigDecimal totalPagar, LocalDateTime fechaHora) {
        // The sequential number is assigned by the persistence layer (the table declares a plain INTEGER key).
        Integer next = jdbcTemplate.queryForObject(
                "SELECT COALESCE(MAX(numero_correlativo), 0) + 1 FROM simulation", Integer.class);
        int numeroCorrelativo = next == null ? 1 : next;

        jdbcTemplate.update(
                "INSERT INTO simulation (numero_correlativo, monto, plazo, tasa_anual, cuota_mensual, "
                        + "total_pagar, fecha_hora) VALUES (?, ?, ?, ?, ?, ?, ?)",
                numeroCorrelativo,
                monto,
                plazo,
                tasaAnual,
                cuotaMensual,
                totalPagar,
                fechaHora == null ? null : Timestamp.valueOf(fechaHora));

        return numeroCorrelativo;
    }
}
